function longestDistinctJoin(words: string[]): number {
  const n = words.length;
  let best = 0;
  for (let s = 0; s < 1 << n; s++) {
    let joined = "";
    for (let i = 0; i < n; i++) if (s & (1 << i)) joined += words[i];
    if (new Set(joined).size === joined.length) best = Math.max(best, joined.length);
  }
  return best;
}

