function longestDistinctJoin(words: string[]): number {
  const masks: number[] = [];
  for (const w of words) {
    let m = 0, ok = true;
    for (const ch of w) {
      const bit = 1 << (ch.charCodeAt(0) - 97);
      if (m & bit) { ok = false; break; }
      m |= bit;
    }
    if (ok) masks.push(m);
  }
  const bits = (m: number) => { let c = 0; while (m) { m &= m - 1; c++; } return c; };
  let best = 0;
  const dfs = (i: number, mask: number) => {
    best = Math.max(best, bits(mask));
    for (let j = i; j < masks.length; j++)
      if ((mask & masks[j]) === 0) dfs(j + 1, mask | masks[j]);
  };
  dfs(0, 0);
  return best;
}

