function longestDistinctJoin(words: string[]): number {
  let reach = [0];
  let best = 0;
  for (const w of words) {
    let m = 0, ok = true;
    for (const ch of w) {
      const bit = 1 << (ch.charCodeAt(0) - 97);
      if (m & bit) { ok = false; break; }
      m |= bit;
    }
    if (!ok) continue;
    const add: number[] = [];
    for (const r of reach) if ((r & m) === 0) {
      add.push(r | m);
      best = Math.max(best, (r | m).toString(2).split("1").length - 1);
    }
    reach = reach.concat(add);
  }
  return best;
}

