class Solution:
    def longestDistinctJoin(self, words: List[str]) -> int:
        reach = [0]
        for w in words:
            m = 0
            for ch in w:
                m |= 1 << (ord(ch) - 97)
            if bin(m).count("1") != len(w):
                continue  # the word repeats a letter
            reach += [r | m for r in reach if r & m == 0]
        return max(bin(r).count("1") for r in reach)

